# PR test bench (CPU): run each repo's relevant tests on upstream main, then with our patch applied.
import subprocess, sys, json, os
OUT = "/kaggle/working"; os.makedirs(OUT, exist_ok=True)
def log(k, v):
    print(k, v, flush=True)
    with open(f"{OUT}/summary.jsonl", "a") as f: f.write(json.dumps({k: v}) + chr(10))
def sh(cmd, cwd=None):
    p = subprocess.run(cmd, shell=True, cwd=cwd, capture_output=True, text=True); return p.returncode, (p.stdout + p.stderr)[-2500:]
PATCHES = {"CircuitKIT": 'From 74ba424d6ea8be52defef72fe0ac705c88765c83 Mon Sep 17 00:00:00 2001\nFrom: ShivenduShivu <shivendukumarbadal328@gmail.com>\nDate: Wed, 11 Nov 2026 09:13:17 +0530\nSubject: [PATCH] fix: safety register_* helpers build contrastive pairs and\n pass options through\n\nThe register_* helpers always used pairing_mode="answer_contrastive", where\nthe corrupt prompt is the same as the clean prompt. discover() rejects\nexactly that case ("corrupt prompt identical to their clean prompt"), so\nthe example in this module\'s docstring (eap-ig on advbench) could not run,\nand there was no way to change the mode through the public helpers.\n\n- _register now defaults to "harmful_vs_benign", which matches the module\n  docstring ("pairs each harmful prompt with a benign control").\n- register_* and register_all_safety accept **kwargs and pass them to\n  SafetyPromptAdapter.adapt(): pairing_mode, refusal_token,\n  compliance_token, benign_controls.\n- Added tests for the default pairing and for passing options through.\n---\n src/circuitkit/tasks/safety_datasets.py    | 47 +++++++++++++---------\n tests/data/test_safety_register_pairing.py | 41 +++++++++++++++++++\n 2 files changed, 69 insertions(+), 19 deletions(-)\n create mode 100644 tests/data/test_safety_register_pairing.py\n\ndiff --git a/src/circuitkit/tasks/safety_datasets.py b/src/circuitkit/tasks/safety_datasets.py\nindex 8e95c8a..096c46c 100644\n--- a/src/circuitkit/tasks/safety_datasets.py\n+++ b/src/circuitkit/tasks/safety_datasets.py\n@@ -32,7 +32,7 @@ ready-made entry points for the common ones.\n from __future__ import annotations\n \n import logging\n-from typing import Optional\n+from typing import Any, Optional\n \n logger = logging.getLogger(__name__)\n \n@@ -43,15 +43,23 @@ def _register(\n     hf_split: str,\n     task_name: str,\n     max_records: int = 200,\n-    pairing_mode: str = "answer_contrastive",\n+    pairing_mode: str = "harmful_vs_benign",\n+    **adapter_kwargs: Any,\n ) -> None:\n     """Lazy: load HF data, run SafetyPromptAdapter, register as task_name.\n \n     Args:\n         pairing_mode: Passed through to SafetyPromptAdapter.adapt().\n-            "answer_contrastive" (default) -- same prompt, refusal vs\n-            compliance token.  "harmful_vs_benign" -- different prompts\n-            (Arditi et al. 2024 style).\n+            "harmful_vs_benign" (default) -- each harmful prompt is paired\n+            with a benign control prompt (Arditi et al. 2024 style), which\n+            gives EAP discovery a contrastive signal.  "answer_contrastive"\n+            -- same prompt, refusal vs compliance token; its corrupt prompt\n+            equals the clean prompt, so discovery rejects it as degenerate\n+            unless ``allow_degenerate_corruption`` is set.\n+        **adapter_kwargs: Also passed to SafetyPromptAdapter.adapt(), e.g.\n+            ``refusal_token`` / ``compliance_token`` (useful when a\n+            tokenizer\'s first reply token is not " I" / " Sure") or\n+            ``benign_controls``.\n     """\n     from circuitkit.tasks.registry import is_task_registered, register_task\n \n@@ -70,6 +78,7 @@ def _register(\n         source=hf_path,\n         max_records=max_records,\n         pairing_mode=pairing_mode,\n+        **adapter_kwargs,\n     )\n     if not ds.fully_paired:\n         raise RuntimeError(\n@@ -83,34 +92,34 @@ def _register(\n     )\n \n \n-def register_advbench(max_records: int = 200) -> None:\n+def register_advbench(max_records: int = 200, **kwargs: Any) -> None:\n     """AdvBench (Zou et al. 2023, walledai/AdvBench)."""\n-    _register("walledai/AdvBench", None, "train", "advbench", max_records)\n+    _register("walledai/AdvBench", None, "train", "advbench", max_records, **kwargs)\n \n \n-def register_harmbench(max_records: int = 200) -> None:\n+def register_harmbench(max_records: int = 200, **kwargs: Any) -> None:\n     """HarmBench (Mazeika et al. 2024, walledai/HarmBench)."""\n-    _register("walledai/HarmBench", "standard", "train", "harmbench", max_records)\n+    _register("walledai/HarmBench", "standard", "train", "harmbench", max_records, **kwargs)\n \n \n-def register_sorrybench(max_records: int = 200) -> None:\n+def register_sorrybench(max_records: int = 200, **kwargs: Any) -> None:\n     """Sorry-Bench (sorry-bench/sorry-bench-202410)."""\n-    _register("sorry-bench/sorry-bench-202410", None, "train", "sorrybench", max_records)\n+    _register("sorry-bench/sorry-bench-202410", None, "train", "sorrybench", max_records, **kwargs)\n \n \n-def register_jailbreakbench(max_records: int = 200) -> None:\n+def register_jailbreakbench(max_records: int = 200, **kwargs: Any) -> None:\n     """JailbreakBench-Behaviors (JailbreakBench/JBB-Behaviors)."""\n-    _register("JailbreakBench/JBB-Behaviors", "behaviors", "harmful", "jailbreakbench", max_records)\n+    _register("JailbreakBench/JBB-Behaviors", "behaviors", "harmful", "jailbreakbench", max_records, **kwargs)\n \n \n-def register_truthfulqa(max_records: int = 200) -> None:\n+def register_truthfulqa(max_records: int = 200, **kwargs: Any) -> None:\n     """TruthfulQA (truthful_qa/generation)."""\n-    _register("truthful_qa", "generation", "validation", "truthfulqa", max_records)\n+    _register("truthful_qa", "generation", "validation", "truthfulqa", max_records, **kwargs)\n \n \n-def register_stereoset(max_records: int = 200) -> None:\n+def register_stereoset(max_records: int = 200, **kwargs: Any) -> None:\n     """StereoSet (Anthropic style stereotype benchmark)."""\n-    _register("McGill-NLP/stereoset", "intersentence", "validation", "stereoset", max_records)\n+    _register("McGill-NLP/stereoset", "intersentence", "validation", "stereoset", max_records, **kwargs)\n \n \n _ALL = [\n@@ -123,7 +132,7 @@ _ALL = [\n ]\n \n \n-def register_all_safety(max_records: int = 200) -> dict:\n+def register_all_safety(max_records: int = 200, **kwargs: Any) -> dict:\n     """Register every safety dataset; returns {task_name: ok_bool}.\n     Errors are logged but don\'t propagate so partial failures (e.g.\n     HF gating) don\'t take down the others."""\n@@ -131,7 +140,7 @@ def register_all_safety(max_records: int = 200) -> dict:\n     for fn in _ALL:\n         name = fn.__name__.removeprefix("register_")\n         try:\n-            fn(max_records=max_records)\n+            fn(max_records=max_records, **kwargs)\n             results[name] = True\n         except Exception as exc:  # noqa: BLE001\n             logger.warning(f"Failed to register {name}: {exc}")\ndiff --git a/tests/data/test_safety_register_pairing.py b/tests/data/test_safety_register_pairing.py\nnew file mode 100644\nindex 0000000..a0fc14c\n--- /dev/null\n+++ b/tests/data/test_safety_register_pairing.py\n@@ -0,0 +1,41 @@\n+"""The register_* safety helpers must build pairs that EAP discovery accepts,\n+and must pass adapter options (pairing mode, tokens) through."""\n+from __future__ import annotations\n+\n+import datasets\n+import pytest\n+\n+import circuitkit.tasks.registry as registry\n+from circuitkit.tasks import safety_datasets\n+\n+ROWS = [{"prompt": f"How do I do harmful thing number {i}?"} for i in range(4)]\n+\n+\n+class _FakeStream(list):\n+    def take(self, n):\n+        return _FakeStream(self[:n])\n+\n+\n+@pytest.fixture\n+def captured(monkeypatch):\n+    specs = []\n+    monkeypatch.setattr(datasets, "load_dataset", lambda *a, **k: _FakeStream(ROWS))\n+    monkeypatch.setattr(registry, "is_task_registered", lambda name: False)\n+    monkeypatch.setattr(registry, "register_task", lambda spec: specs.append(spec))\n+    return specs\n+\n+\n+def test_default_pairs_are_contrastive(captured):\n+    safety_datasets.register_jailbreakbench(max_records=4)\n+    records = captured[0].ds.records\n+    assert records\n+    assert all(r.corrupt_prompt != r.clean_prompt for r in records)\n+\n+\n+def test_options_are_passed_through(captured):\n+    safety_datasets.register_advbench(\n+        max_records=4, pairing_mode="answer_contrastive", refusal_token="I", compliance_token="Sure"\n+    )\n+    records = captured[0].ds.records\n+    assert all(r.corrupt_prompt == r.clean_prompt for r in records)\n+    assert all(r.clean_answer == "I" and r.corrupt_answer == "Sure" for r in records)\n-- \n2.52.0.windows.1\n\n', "SafeTune": 'From b20944c510f036d88b67a07ea7260c9975a62bb9 Mon Sep 17 00:00:00 2001\nFrom: ShivenduShivu <shivendukumarbadal328@gmail.com>\nDate: Wed, 11 Nov 2026 02:17:11 +0530\nSubject: [PATCH] fix: correct progress-bar labels in vector extraction and the\n scan() docstring\n\nextract_refusal_direction passes the harmful prompts as safe_prompts to flip\nthe sign of the direction, so the progress bars said "harmless" while it was\nreading the harmful prompts (and the other way round). CAA had the same issue\nwith its positive and negative sets. extract() now takes an optional\nkeyword-only `labels` argument, and both callers pass the right names. The\ndefault labels are unchanged.\n\nAlso fixed the SpectralEntropyMonitor docstring: scan() returns\n(prompt_idx, layer_idx, entropy, z_score), not a 3-tuple.\n---\n .../core/runtime/inference/vector_extraction.py       | 11 ++++++++---\n .../instrumentation/evaluate/suite/spectral.py        |  2 +-\n src/safetune/interventions/steer/caa.py               |  3 ++-\n src/safetune/interventions/steer/refusal_direction.py |  3 ++-\n 4 files changed, 13 insertions(+), 6 deletions(-)\n\ndiff --git a/src/safetune/core/runtime/inference/vector_extraction.py b/src/safetune/core/runtime/inference/vector_extraction.py\nindex 5bcb2a8..a0709d4 100644\n--- a/src/safetune/core/runtime/inference/vector_extraction.py\n+++ b/src/safetune/core/runtime/inference/vector_extraction.py\n@@ -10,7 +10,7 @@ across transformer layers.\n import logging\n import os\n from dataclasses import dataclass, field\n-from typing import Any, Dict, List, Optional\n+from typing import Any, Dict, List, Optional, Tuple\n \n from tqdm.auto import tqdm\n from safetune._refusal_helpers import _get_decoder_layers\n@@ -177,12 +177,17 @@ class SteeringVectorExtractor:\n         self,\n         safe_prompts: List[str],\n         unsafe_prompts: List[str],\n+        *,\n+        labels: Tuple[str, str] = ("harmless", "harmful"),\n     ) -> Dict[int, Any]:\n         """Extract steering vectors from contrast datasets.\n \n         Args:\n             safe_prompts: list of safe/benign prompt strings.\n             unsafe_prompts: list of unsafe/harmful prompt strings.\n+            labels: names shown in the progress bars for the two prompt sets.\n+                Callers that pass other contrast sets (for example harmful\n+                prompts as ``safe_prompts`` to flip the sign) can name them here.\n \n         Returns:\n             dict mapping layer_idx to steering vector (1D tensor).\n@@ -197,8 +202,8 @@ class SteeringVectorExtractor:\n             len(safe_prompts), len(unsafe_prompts), len(self.config.target_layers),\n         )\n \n-        safe_acts = self._collect_activations(safe_prompts, desc="harmless")\n-        unsafe_acts = self._collect_activations(unsafe_prompts, desc="harmful")\n+        safe_acts = self._collect_activations(safe_prompts, desc=labels[0])\n+        unsafe_acts = self._collect_activations(unsafe_prompts, desc=labels[1])\n \n         vectors: Dict[int, Any] = {}\n         for layer_idx in self.config.target_layers:\ndiff --git a/src/safetune/instrumentation/evaluate/suite/spectral.py b/src/safetune/instrumentation/evaluate/suite/spectral.py\nindex 60b4b27..e418f6b 100644\n--- a/src/safetune/instrumentation/evaluate/suite/spectral.py\n+++ b/src/safetune/instrumentation/evaluate/suite/spectral.py\n@@ -165,7 +165,7 @@ class SpectralEntropyMonitor:\n     1. ``calibrate(benign_prompts)``: build per-layer mean and std of the\n        spectral entropy distribution over a corpus of known-safe prompts.\n     2. ``scan(prompts)``: run forward over each prompt, compute per-layer\n-       entropies, return a list of ``(prompt_idx, layer_idx, z_score)`` for\n+       entropies, return a list of ``(prompt_idx, layer_idx, entropy, z_score)`` for\n        layers whose entropy drops below ``-z_threshold`` standard deviations\n        from the calibrated mean.\n     3. ``entropy_trajectory(prompt)``: convenience for analysis. Returns\ndiff --git a/src/safetune/interventions/steer/caa.py b/src/safetune/interventions/steer/caa.py\nindex 1fe69bd..40bc7c1 100644\n--- a/src/safetune/interventions/steer/caa.py\n+++ b/src/safetune/interventions/steer/caa.py\n@@ -97,7 +97,8 @@ def extract_caa_vectors(\n     ext = SteeringVectorExtractor(model, tokenizer, ve_cfg)\n     # Extractor returns ``safe_mean - unsafe_mean``; the CAA convention is\n     # ``positive - negative``, so map positive -> safe_prompts.\n-    vectors = ext.extract(safe_prompts=positive_prompts, unsafe_prompts=negative_prompts)\n+    vectors = ext.extract(safe_prompts=positive_prompts, unsafe_prompts=negative_prompts,\n+                          labels=("positive", "negative"))\n     logger.info("CAA: extracted %d per-layer behavior vectors.", len(vectors))\n     return vectors\n \ndiff --git a/src/safetune/interventions/steer/refusal_direction.py b/src/safetune/interventions/steer/refusal_direction.py\nindex 30ccde2..f297f20 100644\n--- a/src/safetune/interventions/steer/refusal_direction.py\n+++ b/src/safetune/interventions/steer/refusal_direction.py\n@@ -272,7 +272,8 @@ def extract_refusal_direction(\n                 len(harmful_prompts), len(harmless_prompts), n_val, n_val, 2 * n_val)\n     # The extractor\'s convention is ``safe_mean - unsafe_mean``; flip so the\n     # returned direction points *toward* refusal (harmful_mean - harmless_mean).\n-    raw = extractor.extract(safe_prompts=fit_harmful, unsafe_prompts=fit_harmless)\n+    raw = extractor.extract(safe_prompts=fit_harmful, unsafe_prompts=fit_harmless,\n+                            labels=("harmful", "harmless"))\n     directions = {k: v for k, v in raw.items()}\n \n     def _middle_layer() -> int:\n-- \n2.52.0.windows.1\n\n'}
TESTS = {"CircuitKIT": "tests/data/test_safety_register_pairing.py tests/data",
         "SafeTune": "tests/diagnostic/test_vector_extraction.py tests/diagnostic/test_spectral_monitor.py tests/audit/test_S02_caa.py tests/audit/test_E07_spectral.py"}
for repo in ["CircuitKIT"]:
    d = f"/kaggle/working/{repo}"
    sh(f"git clone -q https://github.com/Lexsi-Labs/{repo}.git {d}")
    log(f"{repo}_base", sh("git log --oneline -1", d)[1].strip())
    rc, out = sh(f"{sys.executable} -m pip install -q -e '.[dev]' || {sys.executable} -m pip install -q -e .", d); log(f"{repo}_install_rc", rc)
    sh(f"{sys.executable} -m pip install -q pytest", d)
    open(f"{d}/our.patch", "w").write(PATCHES[repo])
    # before: run only the existing tests (the new test file arrives with the patch)
    rc, out = sh(f"{sys.executable} -m pytest -q -p no:cacheprovider {TESTS[repo].replace('tests/data/test_safety_register_pairing.py ', '')}", d)
    log(f"{repo}_before", {"rc": rc, "tail": out[-900:]})
    rc, out = sh("git -c user.name=x -c user.email=x@x am -q our.patch", d); log(f"{repo}_patch_apply", {"rc": rc, "out": out[-400:]})
    rc, out = sh(f"{sys.executable} -m pytest -q -p no:cacheprovider tests/data", d)
    log(f"{repo}_after_all_tests_data", {"rc": rc, "tail": out[-600:]})
    if repo == "CircuitKIT":   # the new test must fail without the fix: revert the src change only
        sh("git stash -q || true", d); sh("git checkout -q HEAD~1 -- src", d)
        rc, out = sh(f"{sys.executable} -m pytest -q -p no:cacheprovider tests/data/test_safety_register_pairing.py", d)
        log("CircuitKIT_newtest_on_old_src", {"rc": rc, "tail": out[-700:]}); sh("git checkout -q HEAD -- src", d)
log("DONE", True)
